import React, { useCallback, useEffect, useState } from 'react'
import {
  Button,
  Card,
  Col,
  Divider,
  Drawer,
  message,
  Row,
  Spin,
  Typography,
  Tabs,
  Tag,
  Badge,
} from 'antd'
import {
  DownloadOutlined,
  SettingOutlined,
  AppstoreOutlined,
  CheckCircleOutlined,
  SwapOutlined,
  CheckOutlined,
} from '@ant-design/icons'
import service from '@/utils/api'
import useLocale from '@/hooks/useLocale'
import ThemeConfigPanel from './components/ThemeConfigPanel'
import styles from './style.module.less'

const { Title, Text } = Typography
const { TabPane } = Tabs

interface BuiltinTheme {
  id: string
  name: string
  description: string
  author: string
  themeDir: string
}

interface ThemeStatus {
  installed: boolean
  isCurrent?: boolean
}

interface InstalledTheme {
  id: string
  name: string
  description: string
  author: string
  themeDir: string
  version?: string
  builtin: boolean
  isCurrent: boolean
}

const ThemeMarketPage: React.FC = () => {
  const t = useLocale()
  const [themes, setThemes] = useState<BuiltinTheme[]>([])
  const [statusMap, setStatusMap] = useState<Record<string, ThemeStatus>>({})
  const [loading, setLoading] = useState(true)
  const [installing, setInstalling] = useState<string | null>(null)
  const [switching, setSwitching] = useState<string | null>(null)
  const [configModal, setConfigModal] = useState<{
    visible: boolean
    themeId: string
    themeName: string
  }>({ visible: false, themeId: '', themeName: '' })
  const [installedThemes, setInstalledThemes] = useState<InstalledTheme[]>([])
  const [loadingInstalled, setLoadingInstalled] = useState(false)
  const [activeTab, setActiveTab] = useState('market')

  const fetchThemes = useCallback(async () => {
    try {
      const res = await service.get('/hexopro/api/theme/list')
      setThemes(res.data || [])
    } catch (err) {
      message.error(t['theme.list.fetchFailed'] || '获取主题列表失败')
    }
  }, [t])

  const fetchInstalledStatus = useCallback(async () => {
    if (themes.length === 0) return
    const map: Record<string, ThemeStatus> = {}
    await Promise.all(
      themes.map(async (theme) => {
        try {
          const res = await service.get('/hexopro/api/theme/installed', {
            params: { themeId: theme.id },
          })
          map[theme.id] = res.data || { installed: false }
        } catch {
          map[theme.id] = { installed: false }
        }
      })
    )
    setStatusMap(map)
  }, [themes])

  const fetchInstalledThemes = useCallback(async () => {
    setLoadingInstalled(true)
    try {
      const res = await service.get('/hexopro/api/theme/installed/list')
      setInstalledThemes(res.data || [])
    } catch (err) {
      message.error('获取已安装主题列表失败')
    } finally {
      setLoadingInstalled(false)
    }
  }, [])

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      await fetchThemes()
      setLoading(false)
    }
    void load()
  }, [fetchThemes])

  useEffect(() => {
    if (themes.length > 0) {
      void fetchInstalledStatus()
    }
  }, [themes, fetchInstalledStatus])

  useEffect(() => {
    if (activeTab === 'installed') {
      void fetchInstalledThemes()
    }
  }, [activeTab, fetchInstalledThemes])

  const handleInstall = async (themeId: string) => {
    setInstalling(themeId)
    try {
      await service.post('/hexopro/api/theme/install', { themeId })
      message.success(t['theme.install.success'] || '主题安装完成')
      await fetchInstalledStatus()
      // 刷新已安装主题列表
      if (activeTab === 'installed') {
        await fetchInstalledThemes()
      }
    } catch {
      message.error(t['theme.install.failed'] || '安装失败')
    } finally {
      setInstalling(null)
    }
  }

  const handleSwitchTheme = async (themeDir: string) => {
    setSwitching(themeDir)
    try {
      const res = await service.post('/hexopro/api/theme/switch', { themeDir })
      message.success(`${res.data.message} 请稍后刷新页面查看效果`)
      // 延迟刷新数据，等待生成完成
      setTimeout(async () => {
        await fetchInstalledStatus()
        await fetchInstalledThemes()
      }, 3000)
    } catch (err: any) {
      message.error(err?.response?.data?.msg || '切换主题失败')
    } finally {
      setSwitching(null)
    }
  }

  const openConfig = (theme: BuiltinTheme) => {
    setConfigModal({
      visible: true,
      themeId: theme.id,
      themeName: theme.name,
    })
  }

  const closeConfig = () => {
    setConfigModal({
      visible: false,
      themeId: '',
      themeName: '',
    })
  }

  return (
    <div className={styles.container}>
      <Row gutter={[16, 16]}>
        <Col span={24}>
          <Title level={4}>
            <AppstoreOutlined style={{ marginRight: 8 }} />
            {t['theme.market.title'] || '主题市场'}
          </Title>
          <Text type="secondary">
            {t['theme.market.desc'] ||
              '一键安装、切换 Hexo 主题，可视化配置主题参数'}
          </Text>
        </Col>
      </Row>

      <Divider />

      <Tabs activeKey={activeTab} onChange={setActiveTab}>
        <TabPane tab="主题市场" key="market">
          <Spin spinning={loading}>
            <div className={styles.themeGrid}>
              {themes.map((theme) => {
                const status = statusMap[theme.id] || { installed: false, isCurrent: false }
                const isInstalling = installing === theme.id

                return (
                  <Card key={theme.id} className={styles.themeCard} hoverable>
                    <div className={styles.themePreview}>
                      {theme.name}
                    </div>
                    <div className={styles.themeInfo}>
                      <div className={styles.themeName}>{theme.name}</div>
                      <div className={styles.themeDesc}>{theme.description}</div>
                      <div className={styles.themeAuthor}>
                        {t['theme.author'] || '作者'}: {theme.author}
                      </div>
                    </div>
                    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                      {!status.installed ? (
                        <Button
                          type="primary"
                          icon={<DownloadOutlined />}
                          loading={isInstalling}
                          onClick={() => handleInstall(theme.id)}
                        >
                          {t['theme.install'] || '一键安装'}
                        </Button>
                      ) : (
                        <>
                          {status.isCurrent ? (
                            <Button icon={<CheckOutlined />} disabled>
                              当前使用
                            </Button>
                          ) : (
                            <Button
                              type="primary"
                              icon={<SwapOutlined />}
                              loading={switching === theme.themeDir}
                              onClick={() => handleSwitchTheme(theme.themeDir)}
                            >
                              切换
                            </Button>
                          )}
                          <Button
                            icon={<SettingOutlined />}
                            onClick={() => openConfig(theme)}
                          >
                            {t['theme.config'] || '配置'}
                          </Button>
                        </>
                      )}
                    </div>
                  </Card>
                )
              })}
            </div>
          </Spin>
        </TabPane>

        <TabPane
          tab={
            <span>
              已安装主题
              <Badge count={installedThemes.length} style={{ marginLeft: 8 }} showZero />
            </span>
          }
          key="installed"
        >
          <Spin spinning={loadingInstalled}>
            <div className={styles.themeGrid}>
              {installedThemes.map((theme) => (
                <Card key={theme.themeDir} className={styles.themeCard} hoverable>
                  <div className={styles.themePreview}>
                    {theme.name}
                    {theme.isCurrent && (
                      <Tag color="green" className={styles.currentTag}>
                        <CheckCircleOutlined /> 当前使用
                      </Tag>
                    )}
                  </div>
                  <div className={styles.themeInfo}>
                    <div className={styles.themeName}>{theme.name}</div>
                    <div className={styles.themeDesc}>{theme.description || '暂无描述'}</div>
                    <div className={styles.themeAuthor}>
                      作者: {theme.author || '未知'}
                      {theme.version && ` | 版本: ${theme.version}`}
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                    {theme.isCurrent ? (
                      <Button icon={<CheckOutlined />} disabled>
                        当前使用
                      </Button>
                    ) : (
                      <Button
                        type="primary"
                        icon={<SwapOutlined />}
                        loading={switching === theme.themeDir}
                        onClick={() => handleSwitchTheme(theme.themeDir)}
                      >
                        切换到该主题
                      </Button>
                    )}
                    <Button
                      icon={<SettingOutlined />}
                      onClick={() =>
                        openConfig({
                          id: theme.id,
                          name: theme.name,
                          themeDir: theme.themeDir,
                          description: theme.description,
                          author: theme.author,
                        })
                      }
                      disabled={!theme.builtin}
                    >
                      配置
                    </Button>
                  </div>
                </Card>
              ))}
            </div>
          </Spin>
        </TabPane>
      </Tabs>

      <Drawer
        title={`${t['theme.config'] || '配置'} - ${configModal.themeName}`}
        placement="right"
        onClose={closeConfig}
        open={configModal.visible}
        width={700}
        destroyOnClose
        bodyStyle={{ padding: 0 }}
      >
        {configModal.visible && (
          <ThemeConfigPanel
            themeId={configModal.themeId}
            themeName={configModal.themeName}
            onClose={closeConfig}
          />
        )}
      </Drawer>
    </div>
  )
}

export default ThemeMarketPage
